    id bigint NOT NULL,
    identificador text NOT NULL,
    tipo text,
    natureza text,
    objeto text,
    modalidade text,
    status text,
    secao text,
    valor_estimado numeric,
    observacao text,
    sc text,
    link_publico_sei text,
    created_at timestamp with time zone
);


--
-- Name: processos_id_seq; Type: SEQUENCE; Schema: sueq; Owner: -
--

CREATE SEQUENCE sueq.processos_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: processos_id_seq; Type: SEQUENCE OWNED BY; Schema: sueq; Owner: -
--

ALTER SEQUENCE sueq.processos_id_seq OWNED BY sueq.processos.id;


--
-- Name: unidades; Type: TABLE; Schema: sueq; Owner: -
--

CREATE TABLE sueq.unidades (
    id bigint NOT NULL,
    nome text,
    nome_chave text,
    endereco text,
    telefone text,
    ativo boolean,
    created_at timestamp with time zone
);


--
-- Name: unidades_id_seq; Type: SEQUENCE; Schema: sueq; Owner: -
--

CREATE SEQUENCE sueq.unidades_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


--
-- Name: unidades_id_seq; Type: SEQUENCE OWNED BY; Schema: sueq; Owner: -
